CREATE OR REPLACE FUNCTION public.support_cpf_valid(p_value text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE n text; len integer; i integer; s integer; digit integer; BEGIN n:=regexp_replace(p_value,'\D','','g'); IF length(n)<>11 OR n ~ '^(\d)\1{10}$' THEN RETURN false; END IF; FOR len IN 9..10 LOOP s:=0; FOR i IN 1..len LOOP s:=s+substring(n,i,1)::integer*(len+2-i); END LOOP; digit:=((s*10)%11)%10; IF digit<>substring(n,len+1,1)::integer THEN RETURN false; END IF; END LOOP; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.support_cpf_valid(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.support_cpf_valid(text) TO service_role;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.support_cpf_candidate(text,text,text)'::regprocedure) INTO d; d:=replace(d,'IF cnt=1 THEN','IF NOT public.support_cpf_valid(norm) THEN sid:=NULL; cnt:=0; END IF; IF cnt=1 THEN'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.support_mask_cpf_text(p_value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT regexp_replace(p_value,'\m\d{3}\.?\d{3}\.?\d{3}-?(\d{2})\M','***.***.***-\1','g') $$;
REVOKE ALL ON FUNCTION public.support_mask_cpf_text(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.support_mask_cpf_text(text) TO service_role;
CREATE OR REPLACE FUNCTION public.support_mask_suggestion() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.incoming_text:=public.support_mask_cpf_text(NEW.incoming_text); NEW.suggested_text:=public.support_mask_cpf_text(NEW.suggested_text); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.support_mask_suggestion() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER support_suggestion_cpf_mask BEFORE INSERT OR UPDATE OF incoming_text,suggested_text ON public.support_auto_suggestions FOR EACH ROW EXECUTE FUNCTION public.support_mask_suggestion();